package hexadecimal

import (
	"fmt"
	"math"
)

// SyntaxError is returned when the input is not a valid hexadecimal string.
type SyntaxError struct {
	Msg string
}

func (e SyntaxError) Error() string { return e.Msg }

// RangeError is returned when the value does not fit in an int64.
type RangeError struct {
	Msg string
}

func (e RangeError) Error() string { return e.Msg }

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent, computed from first principles without using any conversion
// library.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, SyntaxError{"empty input is not a valid hexadecimal string"}
	}

	var n int64
	for _, c := range in {
		var d int64
		switch {
		case c >= '0' && c <= '9':
			d = int64(c - '0')
		case c >= 'a' && c <= 'f':
			d = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int64(c-'A') + 10
		default:
			return 0, SyntaxError{fmt.Sprintf("invalid hexadecimal character %q", c)}
		}

		// n*16+d must not overflow int64.
		if n > (math.MaxInt64-d)/16 {
			return 0, RangeError{"value out of range for int64"}
		}
		n = n*16 + d
	}
	return n, nil
}

// HandleErrors takes a list of inputs for ParseHex and returns a matching
// list of "none", "syntax", or "range" according to the error returned.
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch err.(type) {
		case nil:
			results[i] = "none"
		case RangeError:
			results[i] = "range"
		default:
			results[i] = "syntax"
		}
	}
	return results
}

